    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 89-year-old patient presents for evaluation 9 years after a total shoulder arthroplasty of the left side. They report new-onset mechanical symptoms. Radiographs are unremarkable. What is a key initial step in evaluating for an aseptic versus septic etiology?', '["Bone scan", "MRI with metal artifact reduction", "Erythrocyte sedimentation rate (ESR) and C-reactive protein (CRP)", "Immediate revision surgery", "Diagnostic arthroscopy"]'::jsonb, 2, 'In evaluating a painful total joint arthroplasty, distinguishing between aseptic loosening and infection is critical. Initial laboratory screening should include ESR and CRP. If these are elevated, an aspiration is usually indicated.'),
